#[path="../src/package_dispatch.rs"] mod package_dispatch;
use package_dispatch::{DurableIntent,PackageDispatchLog,QueueNotSentAttestation};
use baal_transport_service::{Scope,Permit,Receipt,TransportError,multi_leg::{Basket,Leg,Side,ResponseEvidence}};
use serde_json::{Value,json};use sha2::{Digest,Sha256};
use std::{path::PathBuf,fs};
const T:&str="11111111-1111-4111-8111-111111111111";
fn iso(n:i64)->String{chrono::DateTime::from_timestamp_millis(1_792_022_400_000i64+n).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash<T:serde::Serialize>(v:&T)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn path()->PathBuf{let p=std::env::temp_dir().join(format!("package-dispatch-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir(&p).unwrap();p}
fn intent(n:u64)->DurableIntent{
 let legs=json!([{"exchangeId":"101","marketId":"101","side":"NO","quantity":5,"limitPrice":"0.600000","bookHash":"a".repeat(64)},{"exchangeId":"102","marketId":"102","side":"YES","quantity":5,"limitPrice":"0.450000","bookHash":"b".repeat(64)}]);
 let proof=json!({"nonce":n,"runId":"run-1","bankManifestHash":"c".repeat(64),"tournamentId":T,"atMs":1_792_022_400_001i64,"expiresAtMs":1_792_022_409_000i64,"maximumCost":"5.250000","usesFutureCollateral":false,"wireLegs":legs});let digest=hash(&proof);let id=format!("pkg-{digest}");
 let reserve=json!({"type":"live_package_reserve","source":"moloch_live_dispatcher","packageId":id,"proofHash":digest,"bankScope":{"runId":"run-1","bankManifestHash":"c".repeat(64),"tournamentId":T},"receivedAt":iso(1),"expiresAt":iso(9000),"economics":{"maximumCost":"5.250000"},"legs":legs});
 let scope=Scope{tournament_id:T.into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"101".into()),("102".into(),"102".into())].into()};
 let basket=Basket{idempotency_key:format!("run-1:{id}"),tournament_id:T.into(),maximum_cost:"5.250000".into(),relationship_constraint:None,legs:vec![Leg{exchange_id:"101".into(),side:Side::No,quantity:5,limit_price:"0.600000".into()},Leg{exchange_id:"102".into(),side:Side::Yes,quantity:5,limit_price:"0.450000".into()}]};
 let permit=Permit{run_id:"run-1".into(),intent_id:id,owner:"Codex".into(),expires_at_ms:1_792_022_409_000u64,maximum_quantity:10,maximum_cost:"5.250000".into()};DurableIntent::new(proof,reserve,basket,scope,permit,"account-scope").unwrap()
}
fn error(unknown:bool)->TransportError{TransportError{code:if unknown{"TRANSPORT_ERROR"}else{"AUTHORITY_REJECTED"}.into(),status:None,may_have_executed:unknown,retry_after_ms:0,order_id:None,api_code:None}}
fn ack()->Receipt{Receipt{endpoint:"/orders/multi-leg".into(),request_started_at:iso(3010),received_at:iso(3100),status:200,data:json!({"results":[{"index":0,"data":{"orderId":"901","exchangeId":"101","side":"no","action":"buy","quantity":5,"quantityTraded":-5,"remainingQuantity":0,"price":0.6,"fillPrice":0.6,"totalCost":3,"open":false,"all":null}},{"index":1,"data":{"orderId":"902","exchangeId":"102","side":"yes","action":"buy","quantity":5,"quantityTraded":5,"remainingQuantity":0,"price":0.45,"fillPrice":0.45,"totalCost":2.25,"open":false,"all":null}}]})}}
fn attestation(i:&DurableIntent)->QueueNotSentAttestation{QueueNotSentAttestation{queue_scope:"account-scope".into(),observed_at:iso(3100),request:"actual-local-sdk-request".into(),binding:i.queue_binding().clone(),state:json!({"scope":"account-scope","unknown":{},"active":null,"manual_review":false}),completion:json!({"request":"actual-local-sdk-request","binding":i.queue_binding(),"outcome":"not_sent","networkStarted":false})}}
fn zero(p:&std::path::Path,i:&DurableIntent,status:u16)->ResponseEvidence{let response=json!({"error":{"code":"RATE_LIMITED","message":"sanitized"}});let bytes=serde_json::to_vec_pretty(&response).unwrap();let e=ResponseEvidence{private_body_path:p.join("response.body"),private_metadata_path:p.join("response.metadata"),body_sha256:format!("{:x}",Sha256::digest(&bytes)),request_sha256:i.request_hash().into(),status,request_started_at:iso(3010),received_at:iso(3100),complete_body:true};fs::write(&e.private_body_path,bytes).unwrap();fs::write(&e.private_metadata_path,serde_json::to_vec(&json!({"evidence":e,"request":i.request_spec()})).unwrap()).unwrap();e}
#[test]fn interrupted_attempt_survives_restart_and_blocks_replacement_and_retry(){let p=path();let i=intent(1);let id=i.package_id().to_owned();let expected;{let mut l=PackageDispatchLog::open(&p).unwrap();l.intent(i.clone(),&iso(1)).unwrap();l.attempt(&id,&iso(3001)).unwrap();expected=l.record(&id).unwrap();assert!(l.unresolved());assert!(l.attempt(&id,&iso(3002)).is_err());assert!(l.intent(intent(2),&iso(3002)).is_err());}{let mut l=PackageDispatchLog::open(&p).unwrap();assert_eq!(l.record(&id),Some(expected));assert!(l.unresolved());assert_eq!(l.record(&id).unwrap()["admission"]["spec"],serde_json::to_value(i.request_spec()).unwrap());assert_eq!(l.records().len(),1);assert!(l.intent(intent(2),&iso(4000)).is_err());}fs::remove_dir_all(p).unwrap();}
#[test]fn unknown_can_only_resolve_with_genuine_full_ack_and_no_manual_complete(){let p=path();let id=intent(1).package_id().to_owned();{let mut l=PackageDispatchLog::open(&p).unwrap();l.intent(intent(1),&iso(1)).unwrap();l.attempt(&id,&iso(3001)).unwrap();l.unknown(&id,&error(true),&iso(3100)).unwrap();let mut r=ack();r.data["results"][1]["data"]["quantityTraded"]=json!(4);assert!(l.acknowledged(&id,&r,&iso(3200)).is_err());assert!(l.unresolved());} {let mut l=PackageDispatchLog::open(&p).unwrap();assert!(l.unresolved());l.acknowledged(&id,&ack(),&iso(3200)).unwrap();assert!(!l.unresolved());assert_eq!(l.record(&id).unwrap()["outcome"]["receipt"],serde_json::to_value(ack()).unwrap());assert!(l.acknowledged(&id,&ack(),&iso(3300)).is_err());l.intent(intent(2),&iso(3300)).unwrap();}
 // An attempted forged manual completion remains illegal even with a valid
 // chain hash. Local chain integrity alone never supplies outcome authority.
 let journal=p.join("package-dispatch.ndjson");let text=fs::read_to_string(&journal).unwrap();let last:Value=serde_json::from_str(text.lines().last().unwrap()).unwrap();let mut row=json!({"schemaVersion":1,"sequence":last["sequence"].as_u64().unwrap()+1,"previous":last["hash"],"event":{"kind":"complete","packageId":id,"at":iso(3400),"requestHash":intent(1).request_hash()}});row["hash"]=json!(hash(&row));use std::io::Write;let mut file=fs::OpenOptions::new().append(true).open(journal).unwrap();writeln!(file,"{}",row).unwrap();drop(file);assert!(PackageDispatchLog::open(&p).is_err());fs::remove_dir_all(p).unwrap();}
#[test]fn not_sent_requires_original_process_token_and_matching_positive_queue_proof(){let p=path();let i=intent(1);let id=i.package_id().to_owned();let oldtoken;{let mut l=PackageDispatchLog::open(&p).unwrap();l.intent(i.clone(),&iso(1)).unwrap();oldtoken=l.attempt(&id,&iso(3001)).unwrap();}{let mut l=PackageDispatchLog::open(&p).unwrap();assert!(l.not_sent(oldtoken,&error(false),&attestation(&i),&iso(3200)).is_err());assert!(l.unresolved());}fs::remove_dir_all(p).unwrap();
 let p=path();{let mut l=PackageDispatchLog::open(&p).unwrap();l.intent(i.clone(),&iso(1)).unwrap();let token=l.attempt(&id,&iso(3001)).unwrap();let mut q=attestation(&i);q.completion=json!({});assert!(l.not_sent(token,&error(false),&q,&iso(3200)).is_err());assert!(l.unresolved());}fs::remove_dir_all(p).unwrap();
 let p=path();{let mut l=PackageDispatchLog::open(&p).unwrap();l.intent(i.clone(),&iso(1)).unwrap();let token=l.attempt(&id,&iso(3001)).unwrap();l.not_sent(token,&error(false),&attestation(&i),&iso(3200)).unwrap();assert!(!l.unresolved());assert_eq!(l.record(&id).unwrap()["phase"],"not_sent");}{let l=PackageDispatchLog::open(&p).unwrap();assert!(!l.unresolved());}fs::remove_dir_all(p).unwrap();}
#[test]fn original_zero_evidence_and_request_hash_survive_restart_but_changed_files_deny(){let p=path();let i=intent(1);let id=i.package_id().to_owned();let e=zero(&p,&i,429);{let mut l=PackageDispatchLog::open(&p).unwrap();l.intent(i.clone(),&iso(1)).unwrap();l.attempt(&id,&iso(3001)).unwrap();let bad=zero(&p,&i,500);assert!(l.definitive_zero(&id,&bad,&iso(3200)).is_err());let _=zero(&p,&i,429);l.definitive_zero(&id,&e,&iso(3200)).unwrap();assert!(!l.unresolved());}{let l=PackageDispatchLog::open(&p).unwrap();assert_eq!(l.record(&id).unwrap()["phase"],"definitive_zero");}fs::write(&e.private_body_path,b"{}").unwrap();assert!(PackageDispatchLog::open(&p).is_err());fs::remove_dir_all(p).unwrap();}
#[test]fn duplicate_mutation_torn_tail_and_single_writer_are_denied(){let p=path();{let mut l=PackageDispatchLog::open(&p).unwrap();l.intent(intent(1),&iso(1)).unwrap();assert!(l.intent(intent(1),&iso(2)).is_err());assert!(PackageDispatchLog::open(&p).is_err());let journal=p.join("package-dispatch.ndjson");let original=fs::read_to_string(&journal).unwrap();fs::write(&journal,original.replace("account-scope","different-scope")).unwrap();assert!(l.attempt(intent(1).package_id(),&iso(3001)).is_err());assert!(l.unresolved());assert_eq!(l.head()["poisoned"],true);fs::write(&journal,"{").unwrap();}assert!(PackageDispatchLog::open(&p).is_err());fs::remove_dir_all(p).unwrap();}
#[test]fn failure_after_complete_write_poisoned_process_never_returns_send_token(){let p=path();let id=intent(1).package_id().to_owned();{let mut l=PackageDispatchLog::open(&p).unwrap();l.intent(intent(1),&iso(1)).unwrap();l.inject_sync_failure();assert!(l.attempt(&id,&iso(3001)).is_err());assert!(l.unresolved());assert!(l.attempt(&id,&iso(3002)).is_err());assert_eq!(l.head()["poisoned"],true);} // Existing-format complete serial prefix can recover; it is still unresolved.
 {let mut l=PackageDispatchLog::open(&p).unwrap();assert!(l.unresolved());assert!(l.attempt(&id,&iso(3002)).is_err());}fs::remove_dir_all(p).unwrap();}
#[test]fn request_or_proof_changed_is_not_reconstituted_admission(){let i=intent(1);let mut v=serde_json::to_value(&i).unwrap();v["proof"]["runId"]=json!("different");let rebuilt=DurableIntent::new(v["proof"].clone(),v["reserve"].clone(),serde_json::from_value(v["basket"].clone()).unwrap(),serde_json::from_value(v["scope"].clone()).unwrap(),serde_json::from_value(v["permit"].clone()).unwrap(),"account-scope");assert!(rebuilt.is_err());assert_eq!(i.request_spec().body.as_ref().unwrap()["idempotencyKey"],i.basket().unwrap().idempotency_key);}
#[test]fn preexisting_second_intent_cannot_bypass_another_unresolved_attempt(){let p=path();let a=intent(1).package_id().to_owned();let b=intent(2).package_id().to_owned();{let mut l=PackageDispatchLog::open(&p).unwrap();l.intent(intent(1),&iso(1)).unwrap();l.intent(intent(2),&iso(2)).unwrap();l.attempt(&a,&iso(3001)).unwrap();assert!(l.attempt(&b,&iso(3002)).is_err());l.unknown(&a,&error(true),&iso(3100)).unwrap();assert!(l.attempt(&b,&iso(3200)).is_err());}{let mut l=PackageDispatchLog::open(&p).unwrap();assert!(l.attempt(&b,&iso(3300)).is_err());}fs::remove_dir_all(p).unwrap();}
#[test]fn process_clock_regression_cannot_hide_a_later_unknown_outcome(){let p=path();let id=intent(1).package_id().to_owned();{let mut l=PackageDispatchLog::open(&p).unwrap();l.intent(intent(1),&iso(1)).unwrap();l.attempt(&id,&iso(3001)).unwrap();l.unknown(&id,&error(true),&iso(3500)).unwrap();assert!(l.acknowledged(&id,&ack(),&iso(3400)).is_err());assert!(l.unresolved());l.acknowledged(&id,&ack(),&iso(3600)).unwrap();assert!(!l.unresolved());}fs::remove_dir_all(p).unwrap();}

fn portfolio_intent(n:u64)->DurableIntent{
 let base=serde_json::to_value(intent(n)).unwrap();let mut proof=base["proof"].clone();let mut reserve=base["reserve"].clone();
 let portfolio=json!({"version":1,"mode":"whole_unwind","heldFixture":true});proof["portfolio"]=portfolio.clone();reserve["portfolio"]=portfolio;
 proof["grossFunding"]=json!("0.000000");proof["minimumCashProceeds"]=json!("5.250000");proof["wireLegs"][0]["action"]=json!("sell");proof["wireLegs"][1]["action"]=json!("sell");reserve["legs"]=proof["wireLegs"].clone();reserve["economics"]["maximumCost"]=json!("0.000000");
 let digest=hash(&proof);let id=format!("pkg-{digest}");reserve["proofHash"]=json!(digest);reserve["packageId"]=json!(id);let mut permit:Permit=serde_json::from_value(base["permit"].clone()).unwrap();permit.intent_id=id.clone();permit.maximum_cost="0.000000".into();
 let basket=baal_transport_service::multi_leg_portfolio::Basket{idempotency_key:format!("run-1:{id}"),tournament_id:T.into(),maximum_gross_buy_cost:"0.000000".into(),minimum_gross_sell_proceeds:"5.250000".into(),relationship_constraint:None,legs:vec![baal_transport_service::multi_leg_portfolio::Leg{exchange_id:"101".into(),side:Side::No,action:baal_transport_service::multi_leg_portfolio::Action::Sell,quantity:5,limit_price:"0.600000".into()},baal_transport_service::multi_leg_portfolio::Leg{exchange_id:"102".into(),side:Side::Yes,action:baal_transport_service::multi_leg_portfolio::Action::Sell,quantity:5,limit_price:"0.450000".into()}]};
 DurableIntent::new_portfolio(proof,reserve,basket,serde_json::from_value(base["scope"].clone()).unwrap(),permit,"account-scope").unwrap()
}
#[test]fn signed_intent_has_no_legacy_alias_and_reopens_exact_frozen_action(){let p=path();let i=portfolio_intent(1);let id=i.package_id().to_owned();assert!(i.basket().is_err());assert!(i.portfolio_basket().is_some());assert_eq!(i.request_spec().body.as_ref().unwrap()["legs"][0]["action"],"sell");let original=serde_json::to_value(&i).unwrap();{let mut l=PackageDispatchLog::open(&p).unwrap();l.intent(i,&iso(1)).unwrap();}{let l=PackageDispatchLog::open(&p).unwrap();assert_eq!(l.verified_record(&id).unwrap()["admission"],original);}fs::remove_dir_all(p).unwrap();}
#[test]fn signed_unknown_blocks_both_signed_and_legacy_intents(){let p=path();let i=portfolio_intent(1);let id=i.package_id().to_owned();{let mut l=PackageDispatchLog::open(&p).unwrap();l.intent(i,&iso(1)).unwrap();l.attempt(&id,&iso(3001)).unwrap();l.unknown(&id,&error(true),&iso(3100)).unwrap();assert!(l.intent(portfolio_intent(2),&iso(3200)).is_err());assert!(l.intent(intent(3),&iso(3200)).is_err());}{let l=PackageDispatchLog::open(&p).unwrap();assert!(l.unresolved());}fs::remove_dir_all(p).unwrap();}
#[test]fn signed_frozen_request_changed_action_is_not_rebuilt_as_legacy(){let i=portfolio_intent(1);let mut v=serde_json::to_value(&i).unwrap();v["basket"]["legs"][0]["action"]=json!("buy");let result=DurableIntent::new_portfolio(v["proof"].clone(),v["reserve"].clone(),serde_json::from_value(v["basket"].clone()).unwrap(),serde_json::from_value(v["scope"].clone()).unwrap(),serde_json::from_value(v["permit"].clone()).unwrap(),"account-scope");assert!(result.is_err());}
#[test]fn legacy_untagged_basket_bytes_and_original_field_order_are_preserved(){
 #[derive(serde::Serialize)]struct Original{proof:Value,reserve:Value,basket:Basket,scope:Scope,permit:Permit,queue_scope:String,spec:baal_transport_service::RequestSpec,request_hash:String,queue_binding:Value}
 let i=intent(1);let v=serde_json::to_value(&i).unwrap();let old=Original{proof:v["proof"].clone(),reserve:v["reserve"].clone(),basket:serde_json::from_value(v["basket"].clone()).unwrap(),scope:serde_json::from_value(v["scope"].clone()).unwrap(),permit:serde_json::from_value(v["permit"].clone()).unwrap(),queue_scope:"account-scope".into(),spec:i.request_spec().clone(),request_hash:i.request_hash().into(),queue_binding:i.queue_binding().clone()};assert_eq!(serde_json::to_vec(&i).unwrap(),serde_json::to_vec(&old).unwrap());assert!(v["basket"].get("Legacy").is_none());assert!(v["basket"].get("Portfolio").is_none());
}
